// ── Master auth state listener ──
auth.onAuthStateChanged(user => {
  if (user) {
    initRefs(user.uid);
    showApp(user);
    setSyncStatus('connecting');
    startSync();

    const obKey = `fb_onboarded_${user.uid}`;
    const isNew = !localStorage.getItem(obKey);
    if (isNew) {
      setTimeout(() => showOnboarding(obKey), 400);
    }

    // FIX 8: Schedule daily notifications (morning + evening)
    setupNotifications();
  } else {
    hideApp();
    updateFireIcon(0);
  }
});

/* ─────────────────────────────────────────────────────────
   FIX 8 — NOTIFICATIONS
   One morning (8am) + one evening (7pm) reminder.
   Uses Web Notifications API. Falls back gracefully if denied.
   ───────────────────────────────────────────────────────── */
function setupNotifications() {
  if (!('Notification' in window)) return;
  const key = 'fb_notif_permission';
  if (localStorage.getItem(key) === 'denied') return;

  if (Notification.permission === 'default') {
    // Ask once, after a short delay so it's not the first thing user sees
    setTimeout(async () => {
      const result = await Notification.requestPermission();
      localStorage.setItem(key, result);
      if (result === 'granted') scheduleNotifications();
    }, 8000);
  } else if (Notification.permission === 'granted') {
    scheduleNotifications();
  }
}

function scheduleNotifications() {
  // Use Service Worker if available for persistent notifications,
  // else fall back to setTimeout for current session only
  const now   = new Date();
  const hh    = now.getHours();
  const mm    = now.getMinutes();
  const ss    = now.getSeconds();

  function msUntil(targetHour, targetMin = 0) {
    let ms = ((targetHour - hh) * 60 + (targetMin - mm)) * 60000 - ss * 1000;
    if (ms < 0) ms += 24 * 60 * 60 * 1000; // next day
    return ms;
  }

  // Morning reminder at 8:00 am
  const morningKey = `fb_notif_morning_${todayStr()}`;
  if (!localStorage.getItem(morningKey)) {
    setTimeout(() => {
      if (Notification.permission !== 'granted') return;
      const pending = tasks.filter(t => t.date === todayStr() && !t.done).length;
      new Notification('Good morning ☀️ — FocusBook', {
        body: pending > 0
          ? `You have ${pending} task${pending > 1 ? 's' : ''} planned for today. Let's get started!`
          : 'Open FocusBook to plan your day.',
        icon: 'data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32"><text y="28" font-size="28">🔥</text></svg>',
        tag: 'focusbook-morning',
        renotify: false,
      });
      localStorage.setItem(morningKey, '1');
    }, msUntil(8, 0));
  }

  // Evening reminder at 7:00 pm
  const eveningKey = `fb_notif_evening_${todayStr()}`;
  if (!localStorage.getItem(eveningKey)) {
    setTimeout(() => {
      if (Notification.permission !== 'granted') return;
      const done    = tasks.filter(t => t.date === todayStr() && t.done).length;
      const pending = tasks.filter(t => t.date === todayStr() && !t.done).length;
      const msg = pending === 0
        ? `You finished everything today! ${streak.count} day streak 🔥`
        : `${done} done, ${pending} still to go. Finish strong!`;
      new Notification('Evening check-in 🌙 — FocusBook', {
        body: msg,
        icon: 'data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32"><text y="28" font-size="28">🔥</text></svg>',
        tag: 'focusbook-evening',
        renotify: false,
      });
      localStorage.setItem(eveningKey, '1');
    }, msUntil(19, 0));
  }
}

/* ─────────────────────────────────────────────────────────
   ONBOARDING
   ─────────────────────────────────────────────────────────*/
(function Onboarding() {
  const TOTAL     = 5;
  let   current   = 0;
  let   obDoneKey = null;

  const overlay = document.getElementById('ob-overlay');
  const track   = document.getElementById('ob-track');
  const dots    = document.querySelectorAll('.ob-dot');
  const prevBtn = document.getElementById('ob-prev');
  const nextBtn = document.getElementById('ob-next');
  const skipBtn = document.getElementById('ob-skip');
  const startBtn= document.getElementById('ob-start-btn');

  function goTo(idx) {
    if (idx < 0 || idx >= TOTAL) return;
    current = idx;
    track.style.transform = `translateX(-${idx * 100}%)`;
    dots.forEach((d, i) => d.classList.toggle('active', i === idx));
    prevBtn.style.opacity = idx === 0 ? '0' : '1';
    prevBtn.style.pointerEvents = idx === 0 ? 'none' : 'auto';
    nextBtn.style.display = idx === TOTAL - 1 ? 'none' : 'flex';
  }

  function finish() {
    if (obDoneKey) localStorage.setItem(obDoneKey, '1');
    overlay.classList.add('ob-exit');
    overlay.addEventListener('animationend', () => {
      overlay.style.display = 'none';
      overlay.classList.remove('ob-exit');
      document.body.style.overflow = '';
      // FIX 1: Show area questionnaire after onboarding (first time only)
      const questKey = obDoneKey ? obDoneKey.replace('fb_onboarded_', 'fb_quested_') : null;
      if (questKey && !localStorage.getItem(questKey) && typeof showQuestionnaire === 'function') {
        setTimeout(() => showQuestionnaire(questKey), 300);
        return; // don't auto-open PYD yet — questionnaire will handle flow
      }
    }, { once: true });
    // Trigger morning ritual if it's morning and no tasks yet
    setTimeout(() => {
      if (typeof openPlanYourDay === 'function') {
        // Let shouldShow() in PYD module decide
        const h = new Date().getHours();
        const hasTasks = tasks.filter(t => t.date === todayStr()).length > 0;
        const pydDone  = localStorage.getItem(`pyd_done_${todayStr()}`);
        if (h >= 5 && h < 12 && !hasTasks && !pydDone) {
          setTimeout(openPlanYourDay, 600);
        }
      }
    }, 500);
  }

  nextBtn .addEventListener('click', () => goTo(current + 1));
  prevBtn .addEventListener('click', () => goTo(current - 1));
  skipBtn .addEventListener('click', finish);
  startBtn.addEventListener('click', finish);

  // Swipe support on the track
  let touchStartX = 0;
  track.addEventListener('touchstart', e => { touchStartX = e.touches[0].clientX; }, { passive: true });
  track.addEventListener('touchend',   e => {
    const dx = e.changedTouches[0].clientX - touchStartX;
    if (Math.abs(dx) > 50) dx < 0 ? goTo(current + 1) : goTo(current - 1);
  });

  // Expose to auth flow
  window.showOnboarding = function(key) {
    obDoneKey = key;
    current   = 0;
    overlay.style.display = 'flex';
    overlay.classList.remove('ob-exit');
    overlay.classList.add('ob-enter');
    overlay.addEventListener('animationend', () => overlay.classList.remove('ob-enter'), { once: true });
    document.body.style.overflow = 'hidden';
    track.style.transition = 'none';
    track.style.transform  = 'translateX(0)';
    requestAnimationFrame(() => { track.style.transition = ''; });
    goTo(0);
  };
})();


/* ── STREAK ──────────────────────────────────────────────── */
function updateStreak() {
  const today = todayStr();
  const yest  = (() => { const d=new Date(); d.setDate(d.getDate()-1);
    return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; })();
  if (!tasks.filter(t=>t.date===today).some(t=>t.done)) return;
  if (streak.lastDate === today) return;
  if (streak.lastDate === yest) {
    streak.count++;
  } else {
    streak.count = 1;
    streak.startDate = today;
  }
  streak.lastDate = today;
  if (streak.count > (streak.maxCount || 0)) streak.maxCount = streak.count;
  if (!streak.startDate && streak.count > 0) streak.startDate = today;

  saveMeta();
  document.getElementById('streak-count').textContent = streak.count;
  updateFireIcon(streak.count);
}

/* ── PROGRESS ────────────────────────────────────────────── */
function renderProgress() {
  const today = todayStr();
  const tt    = tasks.filter(t => t.date === today);
  const done  = tt.filter(t => t.done).length;
  const total = tt.length;
  const pct   = total === 0 ? 0 : Math.round(done/total*100);

  const dailyXP = tt.filter(t => t.done).reduce((s, t) => s + xpFor(t.priority), 0);

  document.getElementById('progress-fill').style.width = pct + '%';
  document.getElementById('progress-glow').style.width = pct + '%';
  document.getElementById('progress-label').textContent =
    total === 0 ? 'No tasks yet today' : `${done} of ${total} tasks done`;
  
  const dailyXpEl = document.getElementById('daily-xp-value');
  if (dailyXpEl) dailyXpEl.textContent = dailyXP;
  document.getElementById('xp-value').textContent = totalXP;

  // Today count badge
  const rem = tt.filter(t => !t.done).length;
  const cnt = document.getElementById('today-count');
  if (cnt) { cnt.textContent = rem; cnt.style.display = rem > 0 ? 'flex' : 'none'; }

  // End-of-day summary
  if (total > 0 && done === total) {
    const key = `fb_summary_${today}`;
    if (!localStorage.getItem(key)) {
      setTimeout(() => showSummary(done, total), 900);
      localStorage.setItem(key, '1');
    }
  }
}

/* ── XP POP ──────────────────────────────────────────────── */
function showXPPop(amt, x, y) {
  const el = document.getElementById('xp-pop');
  el.textContent = `+${amt} XP`;
  el.style.left = x + 'px'; el.style.top = y + 'px';
  el.classList.remove('animate'); void el.offsetWidth; el.classList.add('animate');
}

/* ── TASK CARD ───────────────────────────────────────────── */
function priorityOrder(p) { return p==='high'?0:p==='medium'?1:2; }

function createTaskCard(task) {
  const card = document.createElement('div');
  card.className = 'task-card';
  card.setAttribute('data-id', task.id);
  card.setAttribute('data-priority', task.priority);
  card.setAttribute('data-done', String(task.done));

  const pLabel = task.priority.charAt(0).toUpperCase() + task.priority.slice(1);
  const aLabel = task.area.charAt(0).toUpperCase() + task.area.slice(1);
  const dateTag = (task.date && task.date !== todayStr() && task.schedule === 'date')
    ? `<span class="badge badge-date">${formatDisplayDate(task.date)}</span>` : '';
  const carriedTag = task.carriedOver
    ? `<span class="badge badge-carried">carried over</span>` : '';
  const ts = task.created ? formatTimestamp(task.created) : '';
  const subItems = Array.isArray(task.subItems) ? task.subItems : [];
  const doneSubCount = subItems.filter(s => s.done).length;
  const subBadge = subItems.length > 0
    ? `<span style="font-family:'Caveat',cursive;font-size:12px;color:var(--ink-faint);margin-left:2px">▸ ${doneSubCount}/${subItems.length}</span>` : '';

  card.innerHTML = `
    <div class="task-card-main">
      <div class="drag-handle" title="Drag to reorder">
        <svg width="10" height="16" viewBox="0 0 10 16" fill="none">
          <circle cx="3" cy="3"  r="1.5" fill="currentColor"/>
          <circle cx="3" cy="8"  r="1.5" fill="currentColor"/>
          <circle cx="3" cy="13" r="1.5" fill="currentColor"/>
          <circle cx="7" cy="3"  r="1.5" fill="currentColor"/>
          <circle cx="7" cy="8"  r="1.5" fill="currentColor"/>
          <circle cx="7" cy="13" r="1.5" fill="currentColor"/>
        </svg>
      </div>
      <div class="task-check">
        <svg class="task-check-svg" width="12" height="12" viewBox="0 0 12 12" fill="none">
          <path d="M2 6l3 3 5-5" stroke="var(--page-bg)" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
      </div>
      <div class="task-body">
        <p class="task-name">${escHtml(task.name)}</p>
        <div class="task-meta">
          <span class="badge badge-${task.priority}">${pLabel}</span>
          <span class="badge badge-${task.area}">${aLabel}</span>
          ${dateTag}${carriedTag}${subBadge}
        </div>
        ${subItems.length > 0 ? `
          <button class="task-subitems-toggle" aria-label="Toggle sub-items">
            <svg class="task-subitems-toggle-arrow" width="14" height="14" viewBox="0 0 10 10" fill="none"><path d="M2 3l3 4 3-4" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>
            ${subItems.length} sub-item${subItems.length !== 1 ? 's' : ''}
          </button>
        ` : ''}
      </div>
      <div class="task-actions">
        <button class="task-action-btn edit" aria-label="Edit task" title="Edit task">
          <svg width="14" height="14" viewBox="0 0 14 14" fill="none">
            <path d="M9.5 2.5l2 2-6.5 6.5H3v-2L9.5 2.5z" stroke="currentColor" stroke-width="1.3" stroke-linejoin="round"/>
          </svg>
        </button>
      </div>
      ${ts ? `<span class="task-timestamp">${ts}</span>` : ''}
    </div>
    ${subItems.length > 0 ? `
      <div class="task-subitems-list">
        ${subItems.map(s => `
          <div class="task-subitem ${s.done ? 'done' : ''}" data-sub-id="${escHtml(s.id)}">
            <button class="task-subitem-check" aria-label="Toggle sub-item">
              ${s.done ? `<svg width="8" height="8" viewBox="0 0 8 8" fill="none"><path d="M1 4l2 2 4-4" stroke="var(--page-bg)" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></svg>` : ''}
            </button>
            <span class="task-subitem-name">${escHtml(s.name)}</span>
          </div>`).join('')}
      </div>` : ''}
  `;

  // Sub-items toggle expand/collapse
  const siToggle = card.querySelector('.task-subitems-toggle');
  const siList   = card.querySelector('.task-subitems-list');
  if (siToggle && siList) {
    if (openSubTaskIds.has(task.id)) {
      siList.classList.add('open');
      siToggle.classList.add('open');
    }
    siToggle.addEventListener('click', e => {
      e.stopPropagation();
      const open = siList.classList.toggle('open');
      siToggle.classList.toggle('open', open);
      if (open) openSubTaskIds.add(task.id);
      else openSubTaskIds.delete(task.id);
    });
    // Sub-item check toggle
    siList.querySelectorAll('.task-subitem-check').forEach(btn => {
      btn.addEventListener('click', async e => {
        e.stopPropagation();
        const subEl = btn.closest('.task-subitem');
        const subId = subEl.dataset.subId;
        const sub   = (task.subItems || []).find(s => s.id === subId);
        if (!sub) return;
        sub.done = !sub.done;
        subEl.classList.toggle('done', sub.done);
        btn.innerHTML = sub.done ? `<svg width="8" height="8" viewBox="0 0 8 8" fill="none"><path d="M1 4l2 2 4-4" stroke="var(--page-bg)" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></svg>` : '';
        await saveTask(task);
        // Auto-complete main task if all sub-tasks are done
        if (!task.done && task.subItems.every(s => s.done)) {
          toggleTask(task.id, e);
        }
      });
    });
  }

  // Check off
  card.querySelector('.task-card-main').addEventListener('click', e => {
    if (e.target.closest('.task-actions') || e.target.closest('.task-subitems-toggle') || e.target.closest('.task-check')) return;
    toggleTask(task.id, e);
  });
  card.querySelector('.task-check').addEventListener('click', e => {
    e.stopPropagation();
    toggleTask(task.id, e);
  });

  // Edit — opens full edit panel
  card.querySelector('.task-action-btn.edit').addEventListener('click', e => {
    e.stopPropagation();
    openEditPanel(task);
  });

  // Long press to delete
  let pressTimer;
  const startPress = (e) => {
    if (e.type === 'touchstart' && e.touches.length > 1) return;
    pressTimer = setTimeout(() => {
      if (window.confirm('Delete this task?')) {
        deleteTask(task.id);
      }
    }, 600);
  };
  const cancelPress = () => clearTimeout(pressTimer);

  const mainArea = card.querySelector('.task-card-main');
  mainArea.addEventListener('mousedown', startPress);
  mainArea.addEventListener('touchstart', startPress, {passive: true});
  mainArea.addEventListener('mouseup', cancelPress);
  mainArea.addEventListener('mouseleave', cancelPress);
  mainArea.addEventListener('touchend', cancelPress);
  mainArea.addEventListener('touchcancel', cancelPress);

  return card;
}

/* ── RENDER TASKS ────────────────────────────────────────── */
function renderTasks() {
  const today = todayStr();

  // TODAY
  const todayList  = document.getElementById('today-list');
  const todayEmpty = document.getElementById('today-empty');
  const todayTasks = tasks.filter(t=>t.date===today)
    .sort((a,b) => {
      const pd = priorityOrder(a.priority) - priorityOrder(b.priority);
      if (pd !== 0) return pd;
      return (a.sortOrder || a.created || 0) - (b.sortOrder || b.created || 0);
    });

  todayList.innerHTML = '';
  todayEmpty.style.display = todayTasks.length ? 'none' : 'flex';
  let lastP = null;
  todayTasks.forEach(t => {
    if (t.priority !== lastP) {
      const h = document.createElement('div');
      h.className = 'task-section-header';
      h.textContent = t.priority.charAt(0).toUpperCase()+t.priority.slice(1)+' priority';
      todayList.appendChild(h); lastP = t.priority;
    }
    todayList.appendChild(createTaskCard(t));
  });

  // Wire up drag-and-drop on the today list after rendering
  initTodayDragDrop();

  // UPCOMING
  const upList  = document.getElementById('upcoming-list');
  const upEmpty = document.getElementById('upcoming-empty');
  const upTasks = tasks.filter(t=>t.schedule==='date'&&t.date>today)
    .sort((a,b)=>a.date.localeCompare(b.date));

  upList.innerHTML = '';
  upEmpty.style.display = upTasks.length ? 'none' : 'flex';
  const byDate = {};
  upTasks.forEach(t=>{ if(!byDate[t.date]) byDate[t.date]=[]; byDate[t.date].push(t); });
  Object.keys(byDate).forEach(date => {
    const g = document.createElement('div'); g.className='date-group';
    const h = document.createElement('div'); h.className='date-group-header'; h.textContent=formatDisplayDate(date);
    g.appendChild(h);
    const l = document.createElement('div'); l.className='task-list';
    byDate[date].sort((a,b)=>priorityOrder(a.priority)-priorityOrder(b.priority))
      .forEach(t=>l.appendChild(createTaskCard(t)));
    g.appendChild(l); upList.appendChild(g);
  });

  // SOMEDAY
  const sdList  = document.getElementById('someday-list');
  const sdEmpty = document.getElementById('someday-empty');
  const sdTasks = tasks.filter(t=>t.schedule==='someday')
    .sort((a,b)=>priorityOrder(a.priority)-priorityOrder(b.priority));

  sdList.innerHTML = '';
  sdEmpty.style.display = sdTasks.length ? 'none' : 'flex';
  sdTasks.forEach(t=>sdList.appendChild(createTaskCard(t)));

  renderProgress();

  // Re-render calendar if open
  if (document.getElementById('cal-inline-wrap').style.display !== 'none') renderCalendar();
}

/* ── TASK ACTIONS ────────────────────────────────────────── */
async function toggleTask(id, event) {
  const task = tasks.find(t=>t.id===id);
  if (!task) return;
  task.done = !task.done;

  // Propagate done state to all sub-items
  if (Array.isArray(task.subItems) && task.subItems.length > 0) {
    task.subItems.forEach(s => { s.done = task.done; });
  }

  if (task.done) {
    // FIX 7: Only award XP on completion if task was NOT pre-planned in morning ritual
    // (PYD pre-awards XP as a planning bonus; individual task completion is the real reward)
    const xp = xpFor(task.priority);
    totalXP += xp;
    if (event) showXPPop(xp, event.clientX-20, event.clientY-40);
    const card = document.querySelector(`[data-id="${id}"]`);
    if (card) { card.classList.add('completing'); setTimeout(()=>card.classList.remove('completing'),500); }
    updateStreak();
  } else {
    totalXP = Math.max(0, totalXP - xpFor(task.priority));
  }
  saveMeta();
  await saveTask(task);
  renderTasks();
}

async function deleteTask(id) {
  const task = tasks.find(t => t.id === id);
  if (!task) return;

  // ── 1. Animate card out ──
  const card = document.querySelector(`[data-id="${id}"]`);
  if (card) {
    card.style.transition = 'transform .25s ease, opacity .25s ease, max-height .3s ease, padding .3s ease, margin .3s ease';
    card.style.maxHeight  = card.offsetHeight + 'px';
    card.style.overflow   = 'hidden';
    void card.offsetWidth; // force reflow
    card.style.transform  = 'translateX(40px)';
    card.style.opacity    = '0';
    await new Promise(r => setTimeout(r, 30));
    card.style.maxHeight  = '0';
    card.style.padding    = '0 16px';
    card.style.marginTop  = '0';
    await new Promise(r => setTimeout(r, 320));
    card.remove();
  }

  // ── 2. Remove from local state immediately (prevents Firestore snapshot from re-adding it) ──
  pendingDeletes.add(id);
  tasks = tasks.filter(t => t.id !== id);
  renderProgress();

  // ── 3. Truncate name for display ──
  const shortName = task.name.length > 32 ? task.name.slice(0, 32) + '…' : task.name;

  // ── 4. Show undo toast (5-second window) ──
  let undone = false;
  showToast({
    type: 'warning',
    message: `"${shortName}" deleted`,
    duration: 5000,
    undoFn: () => {
      undone = true;
      pendingDeletes.delete(id);
      tasks.push(task);
      tasks.sort((a, b) => (a.created||0) - (b.created||0));
      renderTasks();
      showToast({ type: 'success', message: 'Task restored!', duration: 2500 });
    }
  });

  // ── 5. Wait out the undo window, then permanently delete ──
  await new Promise(r => setTimeout(r, 5300));
  if (!undone) {
    await deleteTaskCloud(id);
    pendingDeletes.delete(id);
  }
}

async function addTask(name, priority, area, schedule, date, subItems) {
  // sortOrder places new tasks at end of their priority group
  const groupEnd = Math.max(0, ...tasks
    .filter(t => t.priority === priority)
    .map(t => t.sortOrder || t.created || 0));
  const task = {
    id: Date.now().toString(), name: name.trim(), priority, area, schedule,
    date: schedule==='today' ? todayStr() : schedule==='someday' ? '' : date,
    done: false, carriedOver: false, created: Date.now(),
    sortOrder: groupEnd + 1000,
    subItems: subItems || [],
  };
  await saveTask(task);
  switchTab(schedule==='today'?'today':schedule==='date'?'upcoming':'someday');
}

/* ── CARRYOVER ───────────────────────────────────────────── */
function carryOver() {
  const today = todayStr();
  let penaltyApplied = false;
  tasks.forEach(t => {
    if (!t.done && t.date && t.date < today && (t.schedule==='today'||t.schedule==='date')) {
      // FIX 6: XP penalty for carried-over tasks (lose 10 XP per task)
      const penalty = 10;
      if (!t.carriedOver) {
        // First time being carried over — apply penalty
        totalXP = Math.max(0, totalXP - penalty);
        penaltyApplied = true;
      }
      if (!t.originalDate) t.originalDate = t.date;
      t.date = today; t.schedule = 'today'; t.carriedOver = true;
      saveTask(t);
    }
  });
  if (penaltyApplied) {
    saveMeta();
    showToast({ type:'warning', message:'Carried tasks cost −10 XP each. Finish them today!', duration:4500 });
  }
}

// FIX 5: A day is "perfect" only if ALL tasks were completed WITHOUT carryover
// We store a flag per day-date when carryover happened so calendar can exclude them
function markDayImperfect(dateStr) {
  const key = `fb_imperfect_${dateStr}`;
  localStorage.setItem(key, '1');
}
function isDayImperfect(dateStr) {
  return !!localStorage.getItem(`fb_imperfect_${dateStr}`);
}

/* ── TABS ────────────────────────────────────────────────── */
function switchTab(name) {
  document.querySelectorAll('.tab-btn').forEach(b => {
    b.classList.toggle('active', b.dataset.tab===name);
    b.setAttribute('aria-selected', b.dataset.tab===name?'true':'false');
  });
  document.querySelectorAll('.tab-panel').forEach(p => {
    p.style.display = p.id===`tab-${name}` ? 'block' : 'none';
    p.classList.toggle('active', p.id===`tab-${name}`);
  });
}
document.querySelectorAll('.tab-btn').forEach(b =>
  b.addEventListener('click', () => switchTab(b.dataset.tab))
);

/* ─────────────────────────────────────────────────────────
   ADD / EDIT PANEL
   Single shared bottom-sheet.  Mode: 'add' | 'edit'
   ───────────────────────────────────────────────────────── */
const addPanel     = document.getElementById('add-panel');
const panelOverlay = document.getElementById('panel-overlay');
const taskInput    = document.getElementById('task-input');
const dateInput    = document.getElementById('date-input');
const saveBtn      = document.getElementById('save-btn');
const panelTitle   = document.getElementById('panel-title');

let panelMode    = 'add';
let editingTask  = null;

let sel      = { priority:'high', area: userDefaultArea, schedule:'today' };
let panelSubItems = [];  // sub-items being built in the panel

function setChips(groupId, value) {
  document.querySelectorAll(`#${groupId} .chip`).forEach(c =>
    c.classList.toggle('active', c.dataset.value===value)
  );
}

function renderPanelSubItems() {
  const list = document.getElementById('subitem-list');
  if (!list) return;
  list.innerHTML = '';
  panelSubItems.forEach((s, i) => {
    const item = document.createElement('div');
    item.className = 'subitem-panel-item';
    item.innerHTML = `
      <span class="subitem-panel-num">${i + 1}</span>
      <span class="subitem-panel-name">${escHtml(s.name)}</span>
      <button class="subitem-panel-remove" data-idx="${i}" aria-label="Remove">×</button>`;
    item.querySelector('.subitem-panel-remove').addEventListener('click', () => {
      panelSubItems.splice(i, 1);
      renderPanelSubItems();
    });
    list.appendChild(item);
  });
}

function resetPanel() {
  taskInput.value = '';
  dateInput.style.display = 'none';
  dateInput.value = '';
  sel = { priority:'high', area: userDefaultArea, schedule:'today' };
  panelSubItems = [];
  setChips('priority-chips','high');
  setChips('area-chips', userDefaultArea);
  setChips('schedule-chips','today');
  const subInput = document.getElementById('subitem-input');
  if (subInput) subInput.value = '';
  renderPanelSubItems();
}

// Sub-item add button in panel
(function initSubItemPanel() {
  const subInput = document.getElementById('subitem-input');
  const subAddBtn= document.getElementById('subitem-add-btn');
  if (!subInput || !subAddBtn) return;
  function addSubItem() {
    const name = subInput.value.trim();
    if (!name) return;
    panelSubItems.push({ id: `sub_${Date.now()}_${Math.random().toString(36).slice(2,5)}`, name, done: false });
    renderPanelSubItems();
    subInput.value = '';
    subInput.focus();
  }
  subAddBtn.addEventListener('click', addSubItem);
  subInput.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); addSubItem(); } });
})();

