function showSummary(done, total) {
  const today  = todayStr();
  const earned = tasks.filter(t=>t.date===today&&t.done).reduce((s,t)=>s+xpFor(t.priority),0);
  let bonus=0;
  if (done===total&&total>0) { bonus=50; totalXP+=bonus; saveMeta(); }
  const msgs=['You showed up and got it done.','Consistency is a superpower.','Another day in the books.','Momentum is everything.','Your future self says thank you.'];
  document.getElementById('summary-title').textContent  = done===total?'Perfect day!':`${done} of ${total} done`;
  document.getElementById('summary-sub').textContent    = msgs[Math.floor(Math.random()*msgs.length)];
  document.getElementById('summary-done').textContent   = done;
  document.getElementById('summary-xp').textContent     = earned+(bonus?` +${bonus}`:'');
  document.getElementById('summary-streak').textContent = streak.count;
  document.getElementById('summary-overlay').style.display='flex';
}

